operation.add:
                
use Silkway\System\Library\{
    SeoRedirectService,
    UrlService,
    RequestService,
    ResponseService,
    ConfigService,
    CatalogProductService
};

                
        /* 301 redirect SEO */
        $urlService = new UrlService($this->db);
        $requestService = new RequestService($this->request);
        $responseService = new ResponseService($this->response);
        $configService = new ConfigService($this->config);
        $catalogProductService = new CatalogProductService($this->model_catalog_product);

        $seoRedirectService = new SeoRedirectService(
            $urlService,
            $requestService,
            $responseService,
            $configService,
            $catalogProductService
        );

        $seoRedirectService->redirectCategoryCanonical();
        /* /301 redirect SEO */
